$faqs=[
["category"=>"Basics","question"=>"What is a call center?","answer"=>"A call center manages customer or prospect calls. It uses trained agents, phone systems, routing, workforce planning, supervision, QA, and reporting.","links"=>[]],
["category"=>"Basics","question"=>"What is call center outsourcing?","answer"=>"Call center outsourcing means using an outside provider to run defined inbound, outbound, or blended voice services for your company.","links"=>[["/solutions/customer-experience-solutions","Explore outsourced customer support"]]],
["category"=>"Basics","question"=>"What is the difference between a call center and a contact center?","answer"=>"A call center mainly handles phone calls. A contact center handles voice plus digital channels such as email, chat, SMS, social messaging, and web or in-app support.","links"=>[]],
["category"=>"Services","question"=>"What is an inbound call center?","answer"=>"An inbound call center receives calls from customers. Common work includes customer care, order support, billing questions, reservations, scheduling, technical support, and complaints.","links"=>[]],
["category"=>"Services","question"=>"What is an outbound call center?","answer"=>"An outbound call center places calls. Common work includes lead qualification, appointment setting, follow-up, surveys, renewals, collections support, and service notifications.","links"=>[]],
["category"=>"Services","question"=>"What is a blended call center?","answer"=>"A blended call center handles both inbound and outbound work. Routing rules assign agents based on demand, priorities, skills, and service levels.","links"=>[]],
["category"=>"Staffing","question"=>"How many agents does a call center need?","answer"=>"Staffing depends on volume, call patterns, handle time, service level, hours, shrinkage, occupancy, channels, and skills. Forecasts should use intervals, not simple daily averages.","links"=>[]],
["category"=>"Staffing","question"=>"What is call center shrinkage?","answer"=>"Shrinkage is paid time when agents cannot handle contacts. Examples include training, coaching, meetings, breaks, leave, system issues, and other activities.","links"=>[]],
["category"=>"Staffing","question"=>"What is call center occupancy?","answer"=>"Occupancy is the share of logged-in time agents spend handling contacts or after-call work. Very high occupancy can increase fatigue and reduce quality.","links"=>[]],
["category"=>"Coverage","question"=>"Can an outsourced call center provide 24/7 support?","answer"=>"Yes. Providers can use shifts, multiple delivery locations, or follow-the-sun coverage for nights, weekends, holidays, and continuous operations.","links"=>[["/global-footprint/","Explore delivery locations"]]],
["category"=>"Coverage","question"=>"Can a call center provide multilingual support?","answer"=>"Yes, depending on recruiting availability and program scale. Define each language, skill level, accent expectations, written needs, hours, and whether coverage is dedicated or shared.","links"=>[]],
["category"=>"Cost","question"=>"How much does call center outsourcing cost?","answer"=>"Cost depends on location, complexity, hours, language, volume, team model, technology, management, and compliance. Pricing may be per agent, hour, minute, contact, or outcome.","links"=>[["/insights/how-much-does-bpo-cost-2026","Review outsourcing pricing"]]],
["category"=>"Cost","question"=>"What affects call center pricing?","answer"=>"Main cost drivers include delivery market, call complexity, training time, schedule, skills, forecast stability, occupancy, supervision, QA, technology, and security.","links"=>[]],
["category"=>"Technology","question"=>"What technology does a modern call center use?","answer"=>"Common systems include cloud telephony, call routing, IVR, CRM, ticketing, workforce management, QA tools, knowledge bases, analytics, recording, and reporting.","links"=>[]],
["category"=>"Technology","question"=>"What is interactive voice response (IVR)?","answer"=>"IVR is an automated phone system. It collects caller input and routes or serves the caller based on menus, speech, account data, or intent. Good IVR keeps effort low and access to people clear.","links"=>[]],
["category"=>"Technology","question"=>"Can outsourced agents use our phone system and CRM?","answer"=>"Yes. Providers can often use client systems or an approved provider platform. Define access, recording, data flow, support ownership, integrations, and security duties before launch.","links"=>[["/compliance-security/","Review security controls"]]],
["category"=>"Metrics","question"=>"What is service level in a call center?","answer"=>"Service level measures the share of contacts answered within a set time. For example, a target may require a set percentage of calls answered within a certain number of seconds.","links"=>[]],
["category"=>"Metrics","question"=>"What is average handling time?","answer"=>"Average handling time includes talk time, hold time, and after-call work. It helps with planning, but lowering it without protecting quality can hurt the customer experience.","links"=>[]],
["category"=>"Metrics","question"=>"What is call abandonment rate?","answer"=>"Call abandonment rate is the percentage of callers who hang up before reaching an agent. It is affected by wait time, routing, messages, self-service, and caller tolerance.","links"=>[]],
["category"=>"Metrics","question"=>"Which KPIs should a call center track?","answer"=>"Common KPIs include service level, answer speed, abandonment, handling time, first-contact resolution, CSAT, quality score, adherence, occupancy, transfer rate, and repeat contacts.","links"=>[["/solutions/quality-assurance-outsourcing","Explore call center QA"]]],
["category"=>"Quality","question"=>"How are outsourced calls monitored for quality?","answer"=>"Quality teams review recorded or live calls against an agreed scorecard. They calibrate scoring, find trends, coach agents, and track corrective actions.","links"=>[["/solutions/quality-assurance-outsourcing","View quality assurance services"]]],
["category"=>"Quality","question"=>"Can AI monitor call center interactions?","answer"=>"AI can transcribe, categorize, summarize, redact, search, and flag calls for review. Human QA specialists should still validate findings, interpret context, and manage coaching or compliance decisions.","links"=>[["/insights/ai-in-customer-experience-automation","Read about AI in CX"]]],
["category"=>"Implementation","question"=>"How long does it take to launch an outsourced call center?","answer"=>"Timing depends on hiring, training, phone setup, integrations, scripts, knowledge, security, testing, and team size. Standard programs may launch quickly. Complex or regulated work takes longer.","links"=>[["/contact","Discuss a call center launch"]]],
["category"=>"Security","question"=>"How is payment or personal data protected on calls?","answer"=>"Controls may include secure access, encryption, recording rules, data masking, clean-desk policies, restricted devices, training, monitoring, PCI DSS, and privacy requirements.","links"=>[["/compliance-security/","View compliance and security"]]],
["category"=>"Selection","question"=>"How should a company choose a call center outsourcing provider?","answer"=>"Review call-type experience, leadership, hiring, training, workforce planning, technology, QA, reporting, security, continuity, cultural fit, references, pricing, and scalability.","links"=>[["/about-us","Learn about EmpireOneCX"],["/case-study","View case studies"]]]
];
